<script setup lang="ts">import {computed,ref} from "vue";import {Upload,FileText} from "lucide-vue-next";import AppShell from "@/components/zs/AppShell.vue";import PageHeader from "@/components/zs/PageHeader.vue";import Panel from "@/components/zs/Panel.vue";import DataTable,{type Column} from "@/components/zs/DataTable.vue";import Toolbar from "@/components/zs/Toolbar.vue";import SearchInput from "@/components/zs/SearchInput.vue";import StatusBadge from "@/components/zs/StatusBadge.vue";import ZButton from "@/components/zs/ZButton.vue";import {useAsyncData} from "@/composables/useAsyncData";import {operationsRepository} from "@/services/operations/repository";import {useCompanyStore} from "@/stores/company";import {showToast} from "@/composables/useToast";import {setPageMeta} from "@/lib/page-meta";import type {KnowledgeDocument} from "@/types/operations";setPageMeta("Knowledge Documents","Company documents prepared for permission-aware knowledge search.");const c=useCompanyStore(),s=useAsyncData(()=>operationsRepository.documents(c.activeCompanyId),{watch:[()=>c.activeCompanyId]}),q=ref(''),type=ref('All types'),file=ref<HTMLInputElement|null>(null),rows=computed(()=>(s.data.value??[]).filter(x=>(type.value==='All types'||x.type===type.value)&&x.name.toLowerCase().includes(q.value.toLowerCase())));const columns:Column[]=[{key:'name',header:'Document'},{key:'type',header:'Type'},{key:'owner',header:'Owner'},{key:'date',header:'Uploaded'},{key:'size',header:'Size'},{key:'access',header:'Access'},{key:'status',header:'Index status'}];async function picked(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;const ext=f.name.split('.').pop()?.toLowerCase();const t:KnowledgeDocument['type']=ext==='pdf'?'PDF':ext==='xlsx'||ext==='xls'?'Excel':ext==='docx'||ext==='doc'?'Word':'SOP';await operationsRepository.addDocument(c.activeCompanyId,f.name,t);await s.refresh();showToast('Document uploaded','Indexing is simulated in this frontend preview.','info')}</script><template><AppShell><PageHeader title="Knowledge Documents" description="Upload, classify and monitor secure document indexing"><template #actions><input ref="file" type="file" class="hidden" accept=".pdf,.doc,.docx,.xls,.xlsx" @change="picked"/><ZButton @click="file?.click()"><Upload class="size-4"/>Upload document</ZButton></template></PageHeader><Panel><Toolbar><SearchInput v-model="q" placeholder="Search documents"/><select v-model="type" class="field w-40"><option>All types</option><option>PDF</option><option>Word</option><option>Excel</option><option>SOP</option></select></Toolbar><DataTable :columns="columns" :rows="rows" :min-width="950"><template #name="{row}:{row:KnowledgeDocument}"><div class="flex items-center gap-2"><FileText class="size-4 text-content-brand"/><span class="font-medium text-content">{{row.name}}</span></div></template><template #type="{row}">{{row.type}}</template><template #owner="{row}">{{row.owner}}</template><template #date="{row}">{{row.uploaded_at}}</template><template #size="{row}">{{row.size}}</template><template #access="{row}">{{row.access}}</template><template #status="{row}"><StatusBadge :status="row.status"/></template></DataTable></Panel></AppShell></template>